// useGraphViewport (#2208, epic #2197 slice 2) — the shared transform pan/zoom math. These cover the
// pure helpers behind the hook (the zoom-about-cursor anchor invariant, clamping, and fit centering)
// plus the wheel-listener lifecycle owned by the `setVp` ref callback (#2454).
import { describe, it, expect } from "vitest";
import { renderHook, render, act } from "@testing-library/react";
import { createElement, useState } from "react";
import { useGraphViewport, zoomAboutPoint, fitView, centerView, centeredView, fitBox, centeredBox, counterScaleTransform, type GraphView, type GraphViewport } from "@/shared/ui/layouts/useGraphViewport";

const V0: GraphView = { tx: 0, ty: 0, scale: 1 };

describe("zoomAboutPoint (#2208)", () => {
  it("keeps the world point under the cursor fixed on screen", () => {
    const mx = 300, my = 200;
    // The world point currently under the cursor (screen → world at the OLD view).
    const worldX = (mx - V0.tx) / V0.scale;
    const worldY = (my - V0.ty) / V0.scale;
    const v = zoomAboutPoint(V0, 2, mx, my, 0.28, 2.6);
    expect(v.scale).toBe(2);
    // That same world point must map back to the cursor under the NEW view.
    expect(worldX * v.scale + v.tx).toBeCloseTo(mx, 6);
    expect(worldY * v.scale + v.ty).toBeCloseTo(my, 6);
  });

  it("holds the anchor invariant from a panned + zoomed start", () => {
    const start: GraphView = { tx: -120, ty: 80, scale: 1.4 };
    const mx = 250, my = 175;
    const worldX = (mx - start.tx) / start.scale;
    const worldY = (my - start.ty) / start.scale;
    const v = zoomAboutPoint(start, 0.7, mx, my, 0.28, 2.6);
    expect(worldX * v.scale + v.tx).toBeCloseTo(mx, 6);
    expect(worldY * v.scale + v.ty).toBeCloseTo(my, 6);
  });

  it("clamps the target scale to [min,max]", () => {
    expect(zoomAboutPoint(V0, 99, 0, 0, 0.4, 1.5).scale).toBe(1.5);
    expect(zoomAboutPoint(V0, 0.01, 0, 0, 0.4, 1.5).scale).toBe(0.4);
    expect(zoomAboutPoint(V0, 0.9, 0, 0, 0.4, 1.5).scale).toBe(0.9);
  });
});

describe("fitView (#2208)", () => {
  it("scales the world to leave the padding and centers it", () => {
    // 1000-wide world in a 600-wide viewport, 50px pad per side → 500 usable → 0.5 scale.
    const v = fitView(1000, 1000, 600, 600, 0.28, 2.6, 50, 1.05);
    expect(v.scale).toBeCloseTo(0.5, 6);
    // Centered: (viewport - world*scale)/2 = (600 - 500)/2 = 50.
    expect(v.tx).toBeCloseTo(50, 6);
    expect(v.ty).toBeCloseTo(50, 6);
  });

  it("does not zoom a small world past maxFitScale", () => {
    const v = fitView(100, 100, 2000, 2000, 0.28, 2.6, 70, 1.05);
    expect(v.scale).toBe(1.05);
  });

  it("respects the min/max floor over the fit", () => {
    // A huge world would want a tiny scale, but min floors it.
    const v = fitView(10000, 10000, 400, 400, 0.4, 1.5, 20, 1.5);
    expect(v.scale).toBe(0.4);
  });
});

describe("centeredView (#2545)", () => {
  it("centers the world at an explicit scale", () => {
    // 800×600 world, 1000×600 viewport, scale 0.5 → world renders 400×300, centered.
    const v = centeredView(800, 600, 1000, 600, 0.5, 0.28, 2.6);
    expect(v.scale).toBe(0.5);
    expect(v.tx).toBe((1000 - 400) / 2); // 300
    expect(v.ty).toBe((600 - 300) / 2);  // 150
  });

  it("clamps the scale to [min,max]", () => {
    expect(centeredView(100, 100, 400, 400, 99, 0.4, 1.5).scale).toBe(1.5);
    expect(centeredView(100, 100, 400, 400, 0.01, 0.4, 1.5).scale).toBe(0.4);
  });

  it("keeps a tall world vertically on-screen where a zoom-about-center replay from origin would not (#2545)", () => {
    // The org bug: an 800-tall world in a 600-tall viewport, saved zoom 0.7. Restoring via zoomTo
    // replays zoomAboutPoint from the fresh mount's {0,0,1} origin about the viewport center...
    const W = 800, H = 800, CW = 900, CH = 600, saved = 0.7;
    const viaZoomTo = zoomAboutPoint({ tx: 0, ty: 0, scale: 1 }, saved, CW / 2, CH / 2, 0.28, 2.6);
    const worldBottomZoomTo = viaZoomTo.ty + H * viaZoomTo.scale;
    expect(worldBottomZoomTo).toBeGreaterThan(CH); // overflows the bottom (y+) — the reported bug

    // ...whereas centeredView frames it symmetrically, so top and bottom overhang are equal.
    const centered = centeredView(W, H, CW, CH, saved, 0.28, 2.6);
    const topGap = centered.ty;
    const bottomGap = CH - (centered.ty + H * centered.scale);
    expect(topGap).toBeCloseTo(bottomGap, 6);
  });
});

describe("centeredBox / fitBox (#2673 — frame the content box, not a nominal origin box)", () => {
  it("centeredBox offsets by the box origin so an off-origin box lands centered", () => {
    // A box at (100,200) sized 400×300 in a 1000×600 viewport at scale 1: its extent centers to
    // (600/2, 300/2) then shifts back by the origin. tx = (1000-400)/2 - 100 = 200; ty = (600-300)/2 - 200 = -50.
    const v = centeredBox({ x: 100, y: 200, w: 400, h: 300 }, 1000, 600, 1, 0.28, 2.6);
    expect(v.tx).toBeCloseTo(200, 6);
    expect(v.ty).toBeCloseTo(-50, 6);
    // The box's CENTER maps to the viewport center under the resulting view.
    expect((100 + 400 / 2) * v.scale + v.tx).toBeCloseTo(1000 / 2, 6);
    expect((200 + 300 / 2) * v.scale + v.ty).toBeCloseTo(600 / 2, 6);
  });

  it("centeredView is the box-at-origin case of centeredBox (unchanged behavior)", () => {
    expect(centeredView(800, 600, 1000, 600, 0.5, 0.28, 2.6))
      .toEqual(centeredBox({ x: 0, y: 0, w: 800, h: 600 }, 1000, 600, 0.5, 0.28, 2.6));
  });

  it("fitBox centers content regardless of where it sits — the org 'parked high' regression", () => {
    // Content biased into the upper part of a big canvas (like the org fleet ~978×536 in 1120×800): fitting
    // the CANVAS box leaves it high, but fitting the CONTENT box centers it. Its center lands at the
    // viewport center, so top and bottom margins are equal.
    const content = { x: 60, y: 48, w: 978, h: 536 };
    const CW = 900, CH = 600;
    const v = fitBox(content, CW, CH, 0.4, 1.5, 20, 1.5);
    const cx = content.x + content.w / 2, cy = content.y + content.h / 2;
    expect(cx * v.scale + v.tx).toBeCloseTo(CW / 2, 6);
    expect(cy * v.scale + v.ty).toBeCloseTo(CH / 2, 6);
    const topMargin = content.y * v.scale + v.ty;
    const bottomMargin = CH - ((content.y + content.h) * v.scale + v.ty);
    expect(topMargin).toBeCloseTo(bottomMargin, 6); // symmetric — not parked high
    expect(topMargin).toBeGreaterThan(0);           // fully on-screen (no top clipping)
  });
});

describe("centerView (#2525)", () => {
  it("pans a world point to the viewport center, keeping the current zoom", () => {
    const v: GraphView = { tx: 0, ty: 0, scale: 2 };
    const r = centerView(v, 800, 600, 100, 50);
    expect(r.scale).toBe(2);            // zoom is untouched (least-disruptive focus)
    expect(r.tx).toBe(800 / 2 - 100 * 2); // 400 - 200 = 200
    expect(r.ty).toBe(600 / 2 - 50 * 2);  // 300 - 100 = 200
    // The centered world point maps back to the viewport center under the new view.
    expect(100 * r.scale + r.tx).toBe(400);
    expect(50 * r.scale + r.ty).toBe(300);
  });
});

// One wheel notch at deltaY -120 → scale × e^(120·0.0016) (the hook's zoom rate).
const NOTCH = Math.exp(120 * 0.0016);

const wheel = (el: HTMLElement, init: WheelEventInit = {}) =>
  el.dispatchEvent(new WheelEvent("wheel", { deltaY: -120, cancelable: true, ...init }));

// #3433 — the INITIAL framing. A page's own fit is a mount effect, so it frames whatever model exists at
// mount, and every graph page loads its data async: that is the EMPTY model. `buildGraph` sizes the world
// tightly around its content, so an empty graph is a small-but-valid box (Glance: 266x156) — `fitBox` caps
// at `maxFitScale` and centers THAT, parking world origin near the middle of the viewport. The real data
// then arrived, the world grew, and nothing re-framed it: the graph rendered from screen center off the
// bottom-right. #2554 had removed `model` from Glance's fit deps (correctly — a fresh model reference every
// status poll re-fit the graph constantly), which left nothing watching for the first real layout.
describe("useGraphViewport initial fit (#3433)", () => {
  const VW = 1600, VH = 900;
  /** A viewport element with a real size — jsdom reports 0, which would make every fit degenerate. */
  const sizedEl = (w = VW, h = VH) => {
    const el = document.createElement("div");
    Object.defineProperty(el, "clientWidth", { value: w, configurable: true });
    Object.defineProperty(el, "clientHeight", { value: h, configurable: true });
    return el;
  };
  /** Let the effect's requestAnimationFrame land. */
  const flush = async () => { await act(async () => { await new Promise((r) => setTimeout(r, 20)); }); };

  const mount = async (w: number, h: number) => {
    const r = renderHook(({ world }) => useGraphViewport(world), { initialProps: { world: { w, h } } });
    act(() => r.result.current.setVp(sizedEl()));
    await flush();
    return r;
  };

  it("re-frames when the data lands and the world grows (the regression)", async () => {
    const { result, rerender } = await mount(266, 156);   // the empty Glance model
    // Framed the empty box: capped at maxFitScale, world origin parked near the viewport middle — which is
    // exactly why node #1 (world 70,70) rendered dead center.
    expect(result.current.view.scale).toBeCloseTo(1.05, 6);
    expect(result.current.view.tx).toBeGreaterThan(VW / 3);

    rerender({ world: { w: 1000, h: 2600 } });            // …the real projects arrive
    await flush();
    expect(result.current.view).toEqual(fitView(1000, 2600, VW, VH, 0.28, 2.6, 70, 1.05));
    // Height constrains, so the content now sits one fitPad from the top rather than mid-screen.
    expect(result.current.view.ty).toBeCloseTo(70, 6);
  });

  it("does NOT re-fit when the model re-renders at the SAME world size (#2554 preserved)", async () => {
    // A status poll hands back a fresh model object every few seconds but moves no node, so the world
    // dimensions are identical. Depending on the model reference here is what wiped the user's pan/zoom.
    const { result, rerender } = await mount(1000, 2600);
    act(() => result.current.centerOn(500, 1300));        // programmatic move, not a user gesture
    const parked = result.current.view;
    rerender({ world: { w: 1000, h: 2600 } });            // new object, same numbers
    await flush();
    expect(result.current.view).toEqual(parked);
  });

  it("stops re-fitting once the USER has panned", async () => {
    const { result, rerender } = await mount(266, 156);
    act(() => result.current.panBy(120, -40));
    const moved = result.current.view;
    rerender({ world: { w: 1000, h: 2600 } });            // a layout change must not yank their viewport
    await flush();
    expect(result.current.view).toEqual(moved);
  });

  it("stops re-fitting once the USER has zoomed", async () => {
    const { result, rerender } = await mount(266, 156);
    const el = sizedEl();
    act(() => result.current.setVp(el));
    act(() => { wheel(el, { clientX: 400, clientY: 300 }); });
    const zoomed = result.current.view;
    rerender({ world: { w: 1000, h: 2600 } });
    await flush();
    expect(result.current.view).toEqual(zoomed);
  });

  it("an EXPLICIT fit still works after the user has taken over", async () => {
    // The drill in/out re-fit and the toolbar button call `fit()` directly — never gated on `userMoved`.
    const { result, rerender } = await mount(266, 156);
    act(() => result.current.panBy(200, 200));
    rerender({ world: { w: 1000, h: 2600 } });
    await flush();
    act(() => result.current.fit());
    expect(result.current.view).toEqual(fitView(1000, 2600, VW, VH, 0.28, 2.6, 70, 1.05));
  });
});

describe("useGraphViewport wheel listener lifecycle (#2454)", () => {
  // The wheel paints IMPERATIVELY and tells React once the gesture settles (#zoom-re-renders-react-on-
  // every-wheel-tick), the same contract the drag has had since #4140 — so `result.current.view` is
  // eventually-consistent during a gesture and these tests have to let it settle before reading it.
  // Without this, three of them failed and a fourth passed VACUOUSLY: it compared the uncommitted view
  // against itself, so its invariant held trivially.
  const settle = async () => {
    await act(async () => { await new Promise((r) => setTimeout(r, 160)); });
  };

  it("zooms a viewport element attached AFTER the hook mounts", async () => {
    // Regression: Design Studio mounts the hook while the center pane shows the Library view, so
    // the canvas element only arrives later. The old mount effect ran once against an empty ref
    // and never re-attached — scroll-zoom stayed permanently dead.
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    let cancelled = false;
    act(() => { cancelled = !wheel(el, { clientX: 300, clientY: 200 }); });
    await settle();
    expect(result.current.view.scale).toBeCloseTo(NOTCH, 6);
    // Non-passive: the handler preventDefaults the page scroll.
    expect(cancelled).toBe(true);
  });

  it("keeps the world point under the cursor fixed across a wheel zoom", async () => {
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const el = document.createElement("div"); // jsdom rect at (0,0) → viewport coords = client coords
    act(() => result.current.setVp(el));
    const mx = 300, my = 200;
    const v0 = result.current.view;
    const worldX = (mx - v0.tx) / v0.scale, worldY = (my - v0.ty) / v0.scale;
    act(() => { wheel(el, { clientX: mx, clientY: my }); });
    await settle();
    const v = result.current.view;
    // Assert the zoom actually HAPPENED before checking the anchor — otherwise an unchanged view
    // satisfies the invariant trivially, which is exactly what this test started doing.
    expect(v.scale).toBeCloseTo(NOTCH, 6);
    expect(worldX * v.scale + v.tx).toBeCloseTo(mx, 6);
    expect(worldY * v.scale + v.ty).toBeCloseTo(my, 6);
  });

  it("does not double the listener when setVp repeats the same element", async () => {
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.setVp(el));
    act(() => { wheel(el); });
    await settle();
    expect(result.current.view.scale).toBeCloseTo(NOTCH, 6); // exactly one zoom step, not two
  });

  it("detaches from a replaced element and follows the new one", async () => {
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const a = document.createElement("div");
    const b = document.createElement("div");
    act(() => result.current.setVp(a));
    act(() => result.current.setVp(b));
    act(() => { wheel(a); });
    await settle();
    expect(result.current.view.scale).toBe(1); // the old element is inert
    act(() => { wheel(b); });
    await settle();
    expect(result.current.view.scale).toBeCloseTo(NOTCH, 6);
  });

  it("detaches on unmount (setVp(null)) so the element stops zooming", () => {
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.setVp(null));
    act(() => { wheel(el); });
    expect(result.current.view.scale).toBe(1);
  });

  it("zoomToCentered is a no-op before the viewport mounts, then centers the world at the saved scale (#2545)", () => {
    const { result } = renderHook(() => useGraphViewport({ w: 800, h: 800 }, { min: 0.4, max: 1.5 }));
    // No viewport element yet → the restore call must not move the view (stays at the origin).
    act(() => result.current.zoomToCentered(0.7));
    expect(result.current.view).toEqual({ tx: 0, ty: 0, scale: 1 });
    // Attached: jsdom clientWidth/Height are 0 → centeredView gives tx = (0 - w*s)/2 = -w*s/2.
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.zoomToCentered(0.7));
    expect(result.current.view.scale).toBe(0.7);
    expect(result.current.view.tx).toBe(-800 * 0.7 / 2);
    expect(result.current.view.ty).toBe(-800 * 0.7 / 2);
  });

  it("fit/zoomToCentered frame the contentBounds provider's box when given, not the world (#2673)", () => {
    const bounds = { x: 100, y: 0, w: 200, h: 200 };
    const { result } = renderHook(() => useGraphViewport({ w: 800, h: 800 }, { min: 0.4, max: 1.5, contentBounds: () => bounds }));
    const el = document.createElement("div"); // jsdom clientWidth/Height = 0
    act(() => result.current.setVp(el));
    act(() => result.current.zoomToCentered(0.7));
    // centeredBox(bounds, 0, 0, 0.7): tx = -bounds.w·s/2 - bounds.x·s ; ty = -bounds.h·s/2 - bounds.y·s.
    expect(result.current.view.scale).toBe(0.7);
    expect(result.current.view.tx).toBeCloseTo(-200 * 0.7 / 2 - 100 * 0.7, 6); // -140, not the world's -280
    expect(result.current.view.ty).toBeCloseTo(-200 * 0.7 / 2 - 0, 6);         // -70
  });

  it("falls back to the world box when the contentBounds provider returns null (#2673)", () => {
    const { result } = renderHook(() => useGraphViewport({ w: 800, h: 800 }, { min: 0.4, max: 1.5, contentBounds: () => null }));
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.zoomToCentered(0.7));
    expect(result.current.view.tx).toBe(-800 * 0.7 / 2); // world box, exactly as the #2545 path
  });

  it("panBy translates the view by a raw screen-space delta, keeping zoom (#3190)", () => {
    // The externally-driven pan (an iframe forwarding a non-interactive drag): no mousedown of the
    // viewport's own, so onCanvasDown never fires — panBy nudges tx/ty directly by the screen delta.
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.zoomBy(1.4)); // pan must be independent of the current zoom
    const before = result.current.view;
    expect(before.scale).not.toBe(1); // sanity: we're panning at a non-unit zoom
    act(() => result.current.panBy(30, -12));
    expect(result.current.view.scale).toBe(before.scale);     // zoom untouched
    expect(result.current.view.tx).toBe(before.tx + 30);      // screen px map 1:1 (translate applied after scale)
    expect(result.current.view.ty).toBe(before.ty - 12);
    // Deltas accumulate across a drag's successive moves.
    act(() => result.current.panBy(-5, 4));
    expect(result.current.view.tx).toBe(before.tx + 25);
    expect(result.current.view.ty).toBe(before.ty - 8);
  });

  it("zoomAtClient zooms about a PAGE point, keeping the world point under it fixed (#3190)", () => {
    // The forwarded-wheel path: the host is handed the cursor's PAGE coords and converts them to
    // viewport-relative via the live rect (jsdom rect is at 0,0 → page == viewport-relative). The world
    // point under the cursor must map to the SAME screen position before and after — the anchor invariant.
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }, { min: 0.2, max: 5 }));
    const el = document.createElement("div"); // jsdom getBoundingClientRect → {left:0, top:0}
    act(() => result.current.setVp(el));
    act(() => result.current.panBy(-40, 15)); // start from a panned view so tx/ty aren't trivially 0
    const cx = 300, cy = 200;
    const before = result.current.view;
    const worldX = (cx - before.tx) / before.scale, worldY = (cy - before.ty) / before.scale;
    act(() => result.current.zoomAtClient(1.5, cx, cy));
    const after = result.current.view;
    expect(after.scale).toBeCloseTo(before.scale * 1.5, 6);            // scaled by the factor
    expect(worldX * after.scale + after.tx).toBeCloseTo(cx, 6);        // point under the cursor held fixed
    expect(worldY * after.scale + after.ty).toBeCloseTo(cy, 6);
  });

  it("zoomAtClient is a no-op before the viewport mounts, and clamps the scale to [min,max] (#3190)", () => {
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }, { min: 0.4, max: 1.5 }));
    act(() => result.current.zoomAtClient(2, 10, 10));   // no viewport element yet → no move
    expect(result.current.view).toEqual({ tx: 0, ty: 0, scale: 1 });
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.zoomAtClient(99, 10, 10));  // way past max
    expect(result.current.view.scale).toBe(1.5);
    act(() => result.current.zoomAtClient(0.001, 10, 10)); // way past min
    expect(result.current.view.scale).toBe(0.4);
  });

  it("centerOn pans the given world point toward the viewport center, keeping zoom (#2525)", () => {
    const { result } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    // No-op before the viewport element mounts (no ref yet).
    act(() => result.current.centerOn(200, 100));
    expect(result.current.view).toEqual({ tx: 0, ty: 0, scale: 1 });
    // Attached: jsdom clientWidth/Height are 0 → center is (0,0); tx = 0 - wx*scale (scale 1).
    const el = document.createElement("div");
    act(() => result.current.setVp(el));
    act(() => result.current.centerOn(200, 100));
    expect(result.current.view.scale).toBe(1); // zoom untouched
    expect(result.current.view.tx).toBe(-200);
    expect(result.current.view.ty).toBe(-100);
  });
});

// #3433 — a page that mounts HIDDEN (a background tab) reports 0x0, and fitting against that would set a
// degenerate transform the user then sees on switching to it.
describe("useGraphViewport initial fit skips an unmeasurable viewport (#3433)", () => {
  const flush = async () => { await act(async () => { await new Promise((r) => setTimeout(r, 20)); }); };

  it("leaves the view untouched while the element has no size", async () => {
    const { result } = renderHook(({ world }) => useGraphViewport(world), { initialProps: { world: { w: 1000, h: 2600 } } });
    act(() => result.current.setVp(document.createElement("div"))); // jsdom: clientWidth/Height are 0
    await flush();
    expect(result.current.view).toEqual({ tx: 0, ty: 0, scale: 1 }); // the untouched initial state
  });
});

// ── `the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom`: a world-layer child that must keep
//    a constant SCREEN size, because the live xterm inside it can only hit-test at net CSS scale 1. ──
describe("counterScale (the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom)", () => {
  const mount = () => {
    const { result, rerender } = renderHook(() => useGraphViewport({ w: 1000, h: 1000 }));
    const vp = document.createElement("div");
    const world = document.createElement("div");
    act(() => { result.current.setVp(vp); result.current.setWorld(world); });
    return { result, rerender, vp, world };
  };
  /** One wheel notch, and the scale it produces — the hook's own factor, exp(-deltaY * 0.0016). */
  const NOTCH = Math.exp(0.16);
  const wheel = (el: HTMLElement) =>
    act(() => { el.dispatchEvent(new WheelEvent("wheel", { deltaY: -100, bubbles: true, cancelable: true })); });

  it("counterScaleTransform is exactly the inverse of the world scale", () => {
    expect(counterScaleTransform({ tx: 0, ty: 0, scale: 1 })).toBe("scale(1)");
    expect(counterScaleTransform({ tx: 9, ty: 9, scale: 2 })).toBe("scale(0.5)");
    expect(counterScaleTransform({ tx: 0, ty: 0, scale: 0.5 })).toBe("scale(2)");
  });

  it("paints a registered element IMMEDIATELY, not on the next view change", () => {
    // A morph opened while the graph is already zoomed would otherwise render one frame at the world
    // scale — a visible pop, and a frame in which a click lands on the wrong cell.
    const { result } = mount();
    act(() => result.current.zoomTo(2));
    const el = document.createElement("div");
    act(() => { result.current.counterScale(el); });
    expect(el.style.transform).toBe("scale(0.5)");
  });

  it("repaints every registered element when the view changes, and stops after unregister", () => {
    const { result } = mount();
    const a = document.createElement("div");
    const b = document.createElement("div");
    let dropA = () => {};
    act(() => { dropA = result.current.counterScale(a); result.current.counterScale(b); });

    act(() => result.current.zoomTo(2));
    expect(a.style.transform).toBe("scale(0.5)");
    expect(b.style.transform).toBe("scale(0.5)"); // several morphs open at once is the normal case

    act(() => { dropA(); });
    act(() => result.current.zoomTo(0.5));
    expect(b.style.transform).toBe("scale(2)");
    expect(a.style.transform).toBe("scale(0.5)"); // unregistered — left exactly as it was
  });

  // THE REGRESSION, and the reason this lives on the hook rather than in a consumer's style prop.
  //
  // #4140 made the wheel imperative: the world layer's transform is rewritten every notch while React is
  // told the new scale only once, `WHEEL_SETTLE_MS` after the gesture stops. A counter-scale computed by
  // a consumer from `vp.view.scale` would therefore be stale for the WHOLE of every zoom — i.e. the
  // terminal would be un-clickable exactly while the user is zooming in to click something. Painting it
  // from `applyView`, beside the world transform, is what makes that impossible.
  it("tracks the IMPERATIVE wheel in the same frame, while React's `view` is still stale", () => {
    const { result, vp, world } = mount();
    const el = document.createElement("div");
    act(() => { result.current.counterScale(el); });

    wheel(vp);

    expect(world.style.transform).toContain(`scale(${NOTCH})`); // the world layer has ALREADY moved…
    expect(el.style.transform).toBe(`scale(${1 / NOTCH})`);     // …and the inverse moved WITH it…
    expect(result.current.view.scale).toBe(1);                  // …while React has not been told yet
  });

  it("survives an UNRELATED re-render mid-gesture — a commit cannot leave a stale inverse", () => {
    // `rerender()` is the honest stand-in for "something else in the tree committed": it re-runs the
    // hook without touching the view. A verb like `panBy` would NOT test this — it derives from the
    // COMMITTED view, so it legitimately discards the in-flight zoom rather than exposing a stale write.
    const { result, rerender, vp } = mount();
    const el = document.createElement("div");
    act(() => { result.current.counterScale(el); });
    wheel(vp);
    const during = el.style.transform;
    expect(during).toBe(`scale(${1 / NOTCH})`);
    act(() => { rerender(); });
    expect(el.style.transform).toBe(during);
  });
});

// ── `every-react-driven-view-change-paints-one-commit-stale` ──
//
// These render the REAL world-layer shape: ONE element carrying BOTH `ref={setWorld}` AND
// `style={worldTransform}`, exactly as `ui-graph-canvas` does. That detail is the whole test. A
// `renderHook` harness attaches only the ref, so React never writes the style prop, so the clobber this
// covers is structurally invisible to it — which is precisely why the bug survived this file's other 36
// assertions. `createElement` rather than JSX only because the record's carried test is a `.ts`.
describe("a React-driven view change reaches the world element (every-react-driven-view-change-paints-one-commit-stale)", () => {
  /** Mount the real shape. Queries within THIS render's own container — `getByTestId` is scoped to
   *  `document.body`, so mounting twice in one test finds both and throws. */
  const mountWorld = () => {
    let api: GraphViewport | null = null;
    let bump: () => void = () => {};
    function Host() {
      const vp = useGraphViewport({ w: 1000, h: 1000 });
      const [, setN] = useState(0);
      api = vp;
      bump = () => setN((n) => n + 1);          // an UNRELATED commit: re-renders, never touches the view
      return createElement("div", { "data-testid": "world", ref: vp.setWorld, style: { ...vp.worldTransform } });
    }
    const { container } = render(createElement(Host));
    act(() => { api!.setVp(document.createElement("div")); });
    return {
      world: container.querySelector("[data-testid=world]") as HTMLElement,
      api: () => api!,
      bump: () => act(() => { bump(); }),
    };
  };

  it("zoomTo paints the COMMITTED view, not the previous one", () => {
    // The measurement that opened the item: this read `scale(1)` while `view.scale` read 2. React wrote
    // the fresh transform, then the layout effect overwrote it from a `viewRef` the passive effect had
    // not updated yet — fresh value written and destroyed inside one commit.
    const { world, api } = mountWorld();
    act(() => api().zoomTo(2));
    expect(api().view.scale).toBe(2);
    expect(world.style.transform).toBe("translate(0px,0px) scale(2)");
  });

  it("holds for every OTHER React-driven verb too — one ordering bug, several symptoms", () => {
    // Enumerated rather than sampled: they all route through `setView`, so a fix that repaired only the
    // verb someone happened to test would look complete and not be.
    const cases: [string, (v: GraphViewport) => void, string][] = [
      ["zoomBy", (v) => v.zoomBy(2), "translate(0px,0px) scale(2)"],
      ["panBy", (v) => v.panBy(30, -10), "translate(30px,-10px) scale(1)"],
      ["restoreView", (v) => v.restoreView({ tx: 12, ty: 34, scale: 1.5 }), "translate(12px,34px) scale(1.5)"],
      ["centerOn", (v) => v.centerOn(0, 0), "translate(0px,0px) scale(1)"],
    ];
    for (const [label, drive, expected] of cases) {
      const { world, api } = mountWorld();
      act(() => drive(api()));
      expect(world.style.transform, label).toBe(expected);
      expect(world.style.transform, `${label} must equal the committed view`)
        .toBe(`translate(${api().view.tx}px,${api().view.ty}px) scale(${api().view.scale})`);
    }
  });

  it("STILL does not snap a live gesture back — #4140's guarantee, which the [view] dep protects", () => {
    // The reason the sync keeps its dependency array. Mid-wheel the committed `view` has not changed, so
    // the sync effect does not re-run and cannot overwrite the live imperative position. Dropping the
    // dep to "simplify" would re-break exactly what #4140 fixed, and no other test here would notice.
    const { world, api, bump } = mountWorld();
    const vpEl = api().vpEl.current!;
    act(() => { vpEl.dispatchEvent(new WheelEvent("wheel", { deltaY: -100, bubbles: true, cancelable: true })); });
    const live = `scale(${Math.exp(0.16)})`;
    expect(world.style.transform).toContain(live);  // the imperative gesture moved it…
    expect(api().view.scale).toBe(1);               // …and React has not committed yet
    bump();                                         // an unrelated commit lands mid-gesture
    expect(world.style.transform).toContain(live);  // the live zoom SURVIVES it
  });
});

// Who owns a wheel gesture inside a graph canvas — the scroller under the pointer, or the canvas?
//
// The canvas zooms on a NON-PASSIVE native `wheel` listener attached to the viewport element
// (`useGraphViewport`). That placement is why this cannot be solved from the child's side: React attaches
// synthetic handlers at the root container, ABOVE the viewport, so a child calling `stopPropagation()` in
// an `onWheel` runs after the viewport's own listener has already zoomed. The decision has to be made
// inside the canvas handler, which is what `overScrollableChild` is for.
//
// `overScrollableChild` is exported precisely so it can be tested here: jsdom reports every layout metric
// as 0, so no amount of rendering can exercise it — the element stubs below supply the metrics instead.
//
// ─────────────────────────────────────────────────────────────────────────────────────────────────
// READ THIS BEFORE DEBUGGING "THE GRAPH STILL ZOOMS OVER A TERMINAL". Two claims elsewhere in this file
// were wrong, cost two rounds of fixes, and are corrected here rather than deleted, so the next reader
// does not re-derive them:
//
//  1. **This guard does NOT cover xterm.** It was written believing "an ancestor that scrolls" reaches
//     xterm's viewport "without naming it". It does not. xterm 6 scrolls SYNTHETICALLY — VS Code's
//     `SmoothScrollableElement` (`.xterm-scrollable-element`) with a drawn scrollbar — so no ancestor of
//     a wheel over terminal text ever reports `scrollHeight > clientHeight`, and this predicate returns
//     false every time. `.xterm-viewport`, the one element that still declares an overflow, is a SIBLING
//     of `.xterm-screen` where the wheel actually lands, so the ancestor walk cannot reach it either.
//     What made it LOOK covered: xterm consumes a wheel (preventDefault + stopPropagation) only when it
//     actually scrolled, so mid-scroll this handler never runs at all — and at the END of the scrollback
//     it does, and zooms. The `overlay` case below is a real property of the predicate; its mention of
//     xterm is provenance for why the branch exists, not evidence that this path is exercised.
//
//  2. **"This cannot be solved from the child's side" is true only of REACT handlers.** React attaches
//     synthetic `onWheel` at the root container, above the viewport, so a synthetic `stopPropagation`
//     does run too late. A NATIVE `addEventListener` on a descendant does not: it fires before this
//     viewport listener in the same bubble phase. That is how the terminal is fixed —
//     `containTerminalWheel` in `@/app/console/lib/terminalWheel`, wired by `TerminalView`, with
//     `terminalWheel.test.ts` asserting the real propagation rather than stubs.
//
// This guard is still correct and still needed for children that DO scroll natively. It is simply not
// the thing that keeps a terminal's wheel out of the canvas.
// ─────────────────────────────────────────────────────────────────────────────────────────────────
import { describe, it, expect, vi, afterEach } from "vitest";
import { overScrollableChild } from "@/shared/ui/layouts/useGraphViewport";

/** An element stub with the three metrics the guard reads, plus a parent chain. */
function el(opts: { overflowY: string; scrollHeight: number; clientHeight: number; scrollTop?: number; parent?: Element | null }) {
  const node = Object.create(Element.prototype) as Element & { parentElement: Element | null };
  Object.defineProperties(node, {
    scrollHeight: { value: opts.scrollHeight },
    clientHeight: { value: opts.clientHeight },
    scrollTop: { value: opts.scrollTop ?? 0, writable: true },
    parentElement: { value: opts.parent ?? null, writable: true },
  });
  STYLES.set(node, opts.overflowY);
  return node;
}

const STYLES = new Map<Element, string>();
const stubStyles = () =>
  vi.stubGlobal("getComputedStyle", (e: Element) => ({ overflowY: STYLES.get(e) ?? "visible" }));

afterEach(() => { vi.unstubAllGlobals(); STYLES.clear(); });

describe("overScrollableChild — the canvas hands the wheel to a scrolling child", () => {
  it("claims the wheel for a scroller AT ITS BOTTOM — the reason this exists", () => {
    // THE BUG. The guard used to require room left in the wheel's direction, so a terminal read down to
    // its last line handed the wheel back and the canvas zoomed — mid-gesture, without the user changing
    // anything about what they were doing. Reading to the end of a session must not throw the graph.
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    const term = el({ overflowY: "auto", scrollHeight: 900, clientHeight: 300, scrollTop: 600, parent: viewport });
    expect(overScrollableChild(term, viewport)).toBe(true);
  });

  it("claims it at the TOP too, scrolling further up", () => {
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    const term = el({ overflowY: "auto", scrollHeight: 900, clientHeight: 300, scrollTop: 0, parent: viewport });
    expect(overScrollableChild(term, viewport)).toBe(true);
  });

  it("does NOT claim it for a child that does not overflow — a short log still zooms the canvas", () => {
    // The case the direction check was mistakenly credited with protecting. It is the OVERFLOW test that
    // protects it, and that test is untouched: a pane with nothing to scroll never owns the wheel.
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    const shortLog = el({ overflowY: "auto", scrollHeight: 200, clientHeight: 300, parent: viewport });
    expect(overScrollableChild(shortLog, viewport)).toBe(false);
  });

  it("does NOT claim it for an overflowing child that cannot scroll (overflow hidden)", () => {
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    const clipped = el({ overflowY: "hidden", scrollHeight: 900, clientHeight: 300, parent: viewport });
    expect(overScrollableChild(clipped, viewport)).toBe(false);
  });

  it("finds a scroller ANY distance up the chain, not just the direct target", () => {
    // The wheel's target is whatever text node's element the pointer is over — xterm renders rows deep
    // inside its viewport, so the scroller is never the target itself.
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    const term = el({ overflowY: "scroll", scrollHeight: 900, clientHeight: 300, parent: viewport });
    const row = el({ overflowY: "visible", scrollHeight: 0, clientHeight: 0, parent: term });
    const span = el({ overflowY: "visible", scrollHeight: 0, clientHeight: 0, parent: row });
    expect(overScrollableChild(span, viewport)).toBe(true);
  });

  it("STOPS at the viewport — the canvas's own scrollability is not a reason to decline", () => {
    // Walking past `stopAt` would let the viewport (or the page) qualify as "a scrollable child" and the
    // canvas would never zoom at all.
    stubStyles();
    const viewport = el({ overflowY: "auto", scrollHeight: 5000, clientHeight: 500 });
    const plain = el({ overflowY: "visible", scrollHeight: 0, clientHeight: 0, parent: viewport });
    expect(overScrollableChild(plain, viewport)).toBe(false);
  });

  it("is false for a non-Element target rather than throwing", () => {
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    expect(overScrollableChild(null, viewport)).toBe(false);
    expect(overScrollableChild(new EventTarget(), viewport)).toBe(false);
  });

  it("treats `overlay` as scrollable — xterm's viewport uses it on some platforms", () => {
    stubStyles();
    const viewport = el({ overflowY: "hidden", scrollHeight: 0, clientHeight: 0 });
    const term = el({ overflowY: "overlay", scrollHeight: 900, clientHeight: 300, scrollTop: 600, parent: viewport });
    expect(overScrollableChild(term, viewport)).toBe(true);
  });
});

// This rule was written as "the OTHER half of the fix" — the reasoning being that once the canvas
// declines to zoom, the browser handles the wheel natively and would chain it to an ancestor, which
// `overscroll-behavior: contain` stops.
//
// THE PREMISE DOES NOT HOLD FOR XTERM, per point 1 at the top of this file: xterm 6 scrolls
// synthetically, so on `.xterm-viewport` there is no native scroll for the browser to chain and the
// declaration is inert for that purpose. It is kept — it costs nothing and is correct for whatever
// native scrolling does happen here — but it is NOT what keeps the graph still. That is
// `containTerminalWheel`, and this assertion is pinned only so the rule is not removed as dead.
describe("the terminal viewport does not chain its scroll outward", () => {
  it("declares overscroll-behavior: contain", async () => {
    const { readFileSync } = await import("node:fs");
    const css = readFileSync("src/styles/tokens.css", "utf8");
    const rule = css.slice(css.indexOf(".app .xterm .xterm-viewport"));
    const body = rule.slice(0, rule.indexOf("}"));
    expect(body).toMatch(/overscroll-behavior:\s*contain/);
    // The scroller itself must still exist, or there is nothing to contain.
    expect(body).toMatch(/overflow-y:\s*auto/);
  });
});
